Patient & Scheduling Service.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(patient_scheduling_service, "Patient & Scheduling Service") {
    Component(PatientManagementComponent, "Patient Management Component", "Spring Webflux / Spring MVC", "Handles patient admissions and electronic medical records requests.")
    Component(SchedulingEngine, "Scheduling Engine", "Java domain-driven service", "Executes scheduling logic and manages transactions with PostgreSQL and Redis.")
    Component(NotificationOrchestrator, "Notification Orchestrator", "Spring Cloud Stream / Spring Integration", "Orchestrates and dispatches alerts via external notification gateways.")
}

Rel(PatientManagementComponent, SchedulingEngine, "Coordinates scheduling workflows")
Rel(SchedulingEngine, NotificationOrchestrator, "Triggers notifications for appointments")

@enduml

Billing & Claims Service.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary("Billing & Claims Service", "Billing & Claims Service") {
    Component("Invoice Management", "Invoice Management", "Spring Boot / Java 21", "Handles patient invoices and billing inquiries.")
    Component("Claims Engine", "Claims Engine", "Spring Boot / Java 21", "Processes and manages insurance claims.")
    Component("Payment Gateway Integration", "Payment Gateway Integration", "Spring Boot / Java 21", "Integrates with external payment gateways for processing financial transactions.")
    Component("Outbox Dispatcher", "Outbox Dispatcher", "Spring Boot / Java 21", "Persists and dispatches transactional messages asynchronously.")
    Component("Notification & Exception Handler", "Notification & Exception Handler", "Spring Boot / Java 21", "Manages notifications and exception handling within the billing and claims workflows.")
}

Rel("Claims Engine", "Outbox Dispatcher", "Persists and dispatches transactional messages", "Internal Java method call")

@enduml
